class Group:
    def __init__(self, members: list[str]) -> None:
        if not members:
            raise ValueError("Group must have at least one member")
        self.members = list(members)
        if len(set(self.members)) != len(self.members):
            raise ValueError("Members must be unique")
        self._member_set = set(self.members)
        self._balances: dict[str, float] = {m: 0.0 for m in self.members}
        # Track balances in integer cents to avoid floating point issues.
        self._cents: dict[str, int] = {m: 0 for m in self.members}

    def add_expense(self, payer: str, amount: float,
                    participants: list[str] | None = None) -> None:
        if payer not in self._member_set:
            raise ValueError(f"Payer {payer!r} is not a group member")
        if amount <= 0:
            raise ValueError("Amount must be positive")

        if participants is None:
            participants = list(self.members)
        else:
            participants = list(participants)

        if not participants:
            raise ValueError("Participants list must not be empty")
        for p in participants:
            if p not in self._member_set:
                raise ValueError(f"Participant {p!r} is not a group member")

        # Convert amount to integer cents.
        total_cents = int(round(amount * 100))
        if total_cents <= 0:
            raise ValueError("Amount must be positive")

        n = len(participants)
        base, remainder = divmod(total_cents, n)

        # Payer paid the full amount.
        self._cents[payer] += total_cents

        # Each participant (including payer) owes their share.
        # Rule 4: leftover cents borne by the payer; others owe rounded-down amount.
        for p in participants:
            if p == payer:
                # Payer's own share includes the remainder.
                share = base + remainder
            else:
                # If payer is not a participant, remainder is simply unallocated
                # via shares — but the payer still paid the remainder "extra",
                # effectively crediting them. Rule 4 only specifies leftover cents
                # are borne by the payer, so non-payer participants owe base.
                share = base + (remainder if payer not in participants else 0)
            self._cents[p] -= share

        # Recompute float balances from cents.
        for m in self.members:
            self._balances[m] = self._cents[m] / 100.0

    def balances(self) -> dict[str, float]:
        return dict(self._balances)

    def settle_up(self) -> list[tuple[str, str, float]]:
        debtors = []
        creditors = []
        for m in self.members:
            c = self._cents[m]
            if c < 0:
                debtors.append([m, -c])
            elif c > 0:
                creditors.append([m, c])

        debtors.sort(key=lambda x: x[1], reverse=True)
        creditors.sort(key=lambda x: x[1], reverse=True)

        payments: list[tuple[str, str, float]] = []
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            debtor, owe = debtors[i]
            creditor, due = creditors[j]
            pay = min(owe, due)
            if pay > 0:
                payments.append((debtor, creditor, pay / 100.0))
            debtors[i][1] -= pay
            creditors[j][1] -= pay
            if debtors[i][1] == 0:
                i += 1
            if creditors[j][1] == 0:
                j += 1

        # At most (members - 1) payments are produced by this greedy matching.
        return payments
